# Fig 1: Signal evolution across generations for multiple synthetic fractions.
# Data: plan001 (WikiText 1.5B) or plan002 (PubMed 1.5B) summary JSONs.
# Layout: 3 subplots — spectral_entropy, stable_rank, perplexity.

import argparse
import os
import sys
import json
import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from paper_style import (
    apply_style, save_fig, load_summary,
    DOUBLE_COL_TALL, FRACTION_COLORS, FRACTION_LABELS, SIGNAL_NAMES,
)
import matplotlib.pyplot as plt


def mock_data():
    data = {}
    np.random.seed(0)
    base = {
        'final_spectral_entropy': 0.645,
        'final_stable_rank': 12.1,
        'perplexity': 7.87,
    }
    drift = {
        'final_spectral_entropy': [0, 0.04, 0.06, 0.08, 0.10],
        'final_stable_rank': [0, 3, 5, 8, 12],
        'perplexity': [0, 15, 30, 40, 50],
    }
    for frac in [0, 50, 100]:
        gens = []
        for g in range(5):
            row = {'generation': g, 'fraction': frac / 100}
            scale = frac / 100
            for sig in base:
                row[sig] = base[sig] + drift[sig][g] * scale + np.random.normal(0, 0.01)
            gens.append(row)
        data[frac] = gens
    return data


def load_real_data(data_dir, fractions, seeds):
    all_data = {}
    for frac in fractions:
        all_data[frac] = {}
        for seed_dir in seeds:
            path = os.path.join(seed_dir, f'summary_{frac}pct.json')
            loaded = load_summary(path)
            if loaded is not None:
                seed_name = os.path.basename(seed_dir)
                all_data[frac][seed_name] = loaded
    return all_data


def aggregate_seeds(seed_data):
    if not seed_data:
        return None, None, None
    n_seeds = len(seed_data)
    seed_lists = list(seed_data.values())
    n_gens = min(len(s) for s in seed_lists)
    signals = ['final_spectral_entropy', 'final_stable_rank', 'perplexity']
    means = {sig: np.zeros(n_gens) for sig in signals}
    stds = {sig: np.zeros(n_gens) for sig in signals}
    for sig in signals:
        vals = np.array([[s[g].get(sig, np.nan) for g in range(n_gens)] for s in seed_lists])
        means[sig] = np.nanmean(vals, axis=0)
        stds[sig] = np.nanstd(vals, axis=0) if n_seeds > 1 else np.zeros(n_gens)
    generations = list(range(n_gens))
    return generations, means, stds


def plot(data_by_frac, fractions, output_path, use_mock=False):
    apply_style()
    signals = ['final_spectral_entropy', 'final_stable_rank', 'perplexity']
    titles = ['Spectral Entropy', 'Stable Rank', 'Perplexity']

    fig, axes = plt.subplots(1, 3, figsize=DOUBLE_COL_TALL)

    for ax, sig, title in zip(axes, signals, titles):
        for frac in fractions:
            color = FRACTION_COLORS.get(frac, '#333333')
            label = FRACTION_LABELS.get(frac, f'{frac}%')

            if use_mock:
                gens_list = data_by_frac[frac]
                x = [r['generation'] for r in gens_list]
                y = [r[sig] for r in gens_list]
                ax.plot(x, y, 'o-', color=color, label=label)
            else:
                seed_data = data_by_frac.get(frac, {})
                if not seed_data:
                    continue
                generations, means, stds = aggregate_seeds(seed_data)
                if generations is None:
                    continue
                ax.plot(generations, means[sig], 'o-', color=color, label=label)
                if np.any(stds[sig] > 0):
                    ax.fill_between(generations,
                                    means[sig] - stds[sig],
                                    means[sig] + stds[sig],
                                    color=color, alpha=0.15)

        ax.set_xlabel('Generation')
        ax.set_ylabel(title)
        ax.set_title(title)
        ax.set_xticks(range(5))

    axes[-1].legend(loc='best', framealpha=0.9)
    fig.tight_layout()
    save_fig(fig, output_path)


def main():
    parser = argparse.ArgumentParser(description='Fig 1: Signal evolution across generations')
    parser.add_argument('--data-dirs', nargs='+', default=None,
                        help='Paths to output dirs (one per seed)')
    parser.add_argument('--fractions', nargs='+', type=int, default=[0, 50, 100],
                        help='Synthetic fractions to plot')
    parser.add_argument('--output', default='fig1_signal_evolution',
                        help='Output path stem (without extension)')
    parser.add_argument('--mock', action='store_true', help='Use mock data for layout testing')
    args = parser.parse_args()

    if args.mock or args.data_dirs is None:
        print('Using mock data')
        data = mock_data()
        plot(data, args.fractions, args.output, use_mock=True)
    else:
        data = load_real_data(None, args.fractions, args.data_dirs)
        plot(data, args.fractions, args.output, use_mock=False)


if __name__ == '__main__':
    main()
